// Blog cover generator for the automated publishing pipeline.
//
// Every blog post gets a 1200x675 (16:9) cover. The generator is
// self-contained: it renders the cover from the post's own frontmatter and
// the brand palette, so it runs on a GitHub Actions ubuntu runner with no
// network access and no local assets. That matters because the daily
// workflow (.github/workflows/daily-polls.yml) publishes posts generated by
// scripts/daily_polls.py, which writes no coverImage fields at all.
//
// Two render paths:
//   photo     - when a directory of real sample photos is available
//               (CIB_IMAGE_DIR, default C:\Users\saonb\blog-image), a random
//               *-cover.jpg is cropped and the title is typeset over it.
//   artwork   - otherwise, a deterministic branded cover is drawn with SVG:
//               a section-tinted gradient, an accent motif, the section
//               kicker, the post title, and a caption slot.
//
// Both write public/assets/blog/<slug>-cover.jpg and patch coverImage /
// coverImageAlt into the post's frontmatter, which BlogPost.astro and
// BlogIndex.astro already consume (along with og:image / twitter:image).
//
// Usage
// -----
//   node scripts/cover-generator.mjs                 # posts missing a cover
//   node scripts/cover-generator.mjs --slug <slug>   # one post
//   node scripts/cover-generator.mjs --all           # every post, every time
//   node scripts/cover-generator.mjs --force         # regenerate even if set
//   node scripts/cover-generator.mjs --mode artwork  # never use photos
//   node scripts/cover-generator.mjs --mode photo    # require photos (CI fails)
//   node scripts/cover-generator.mjs --check         # report gaps, exit 1
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');
const blogDir = path.join(rootDir, 'src', 'content', 'blog');
const outDirDefault = path.join(rootDir, 'public', 'assets', 'blog');
const sampleDir = process.env.CIB_IMAGE_DIR || 'C:\\Users\\saonb\\blog-image';

// public/blog.css
const BRAND = {
  primary: '#ff4d6d',
  secondary: '#6a00f4',
  ink: '#291b2d',
  muted: '#6f6573',
  white: '#ffffff',
};

const WIDTH = 1200;
const HEIGHT = 675;
const MARGIN = 72;
// In-article figures are 3:2, matching the width/height the layout renders.
const BODY_WIDTH = 1200;
const BODY_HEIGHT = 800;
const BODY_START = '<!-- cib:body-image:start -->';
const BODY_END = '<!-- cib:body-image:end -->';
// Font stacks are emitted inside a double-quoted XML attribute, so the
// fallbacks must use single quotes -- raw double quotes terminate the
// attribute and librsvg rejects the whole SVG.
const SERIF = "'Georgia', 'Times New Roman', 'Noto Serif', serif";
const SANS = "'Segoe UI', 'Helvetica Neue', Arial, 'Liberation Sans', sans-serif";

// Section-tinted palettes. The gradient anchors every cover in the site's
// pink/plum identity while keeping the four sections visually distinct.
const PALETTES = {
  Connection: { from: '#ffe4ea', to: '#ffc9d8', accent: '#ff4d6d', deep: '#6a00f4', tint: '#fff1f5' },
  Relationships: { from: '#f3e8ff', to: '#dcc6ff', accent: '#6a00f4', deep: '#ff4d6d', tint: '#f6efff' },
  'Date night': { from: '#2a1040', to: '#5b1a72', accent: '#ff4d6d', deep: '#ffb3c6', tint: '#fff1f5' },
  Seasonal: { from: '#fff0e6', to: '#ffd9c2', accent: '#e0492f', deep: '#6a00f4', tint: '#fff6f0' },
  Friendship: { from: '#e8f4ff', to: '#c9e2ff', accent: '#2f6fe0', deep: '#6a00f4', tint: '#f2f8ff' },
  default: { from: '#fff1f5', to: '#f6efff', accent: '#ff4d6d', deep: '#6a00f4', tint: '#fff1f5' },
};

// Dark palettes need light text; the rest need ink text.
function isDarkPalette(name) {
  return name === 'Date night';
}

function parseArgs(argv) {
  const options = { slug: null, all: false, force: false, check: false, mode: 'auto', out: outDirDefault };
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--all') options.all = true;
    else if (arg === '--force') options.force = true;
    else if (arg === '--check') options.check = true;
    else if (arg === '--slug') options.slug = argv[++i];
    else if (arg === '--mode') options.mode = argv[++i];
    else if (arg === '--out') options.out = argv[++i];
    else if (arg === '--help' || arg === '-h') options.help = true;
    else throw new Error(`unknown argument: ${arg}`);
  }
  return options;
}

function readPost(name) {
  const slug = name.replace(/\.md$/, '');
  const file = path.join(blogDir, name);
  const raw = fs.readFileSync(file, 'utf8');
  const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!match) throw new Error(`${name}: missing frontmatter fence`);
  const frontmatter = {};
  for (const line of match[1].split(/\r?\n/)) {
    const field = line.match(/^([A-Za-z0-9_]+):\s*(.*)$/);
    if (!field) continue;
    const [, key, value] = field;
    frontmatter[key] = value.replace(/^["']|["']$/g, '').trim();
  }
  return { slug, name, file, raw, frontmatter, body: match[2], frontmatterText: match[1] };
}

function listPosts() {
  return fs.readdirSync(blogDir)
    .filter((name) => name.endsWith('.md'))
    .map(readPost);
}

function listSampleCovers() {
  if (!fs.existsSync(sampleDir)) return [];
  return fs.readdirSync(sampleDir)
    .filter((name) => name.toLowerCase().endsWith('-cover.jpg'))
    .sort()
    .map((name) => ({ key: name.replace(/-cover\.jpg$/i, ''), file: path.join(sampleDir, name) }));
}

function escapeXml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function hashSlug(slug, salt = 0) {
  let hash = 7;
  const text = salt ? `${slug}:${salt}` : slug;
  for (let i = 0; i < text.length; i += 1) hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  return hash;
}

// Approximate text width for wrapping without a font-metrics dependency.
function measureLine(text, size, weight) {
  const bold = weight >= 700 ? 1.05 : 1;
  let units = 0;
  for (const char of text) {
    if (char === ' ') units += 0.3;
    else if ('iljtf.,;:\'|!'.includes(char)) units += 0.31;
    else if ('mwMW'.includes(char)) units += 0.95;
    else if (/[A-Z]/.test(char)) units += 0.72;
    else units += 0.56;
  }
  return units * size * bold;
}

function wrapLines(text, size, weight, maxWidth, maxLines) {
  const lines = [];
  let line = '';
  for (const word of text.split(/\s+/).filter(Boolean)) {
    const candidate = line ? `${line} ${word}` : word;
    if (measureLine(candidate, size, weight) <= maxWidth) {
      line = candidate;
      continue;
    }
    if (line) lines.push(line);
    line = word;
  }
  if (line) lines.push(line);
  return lines.slice(0, maxLines);
}

// ---------------------------------------------------------------------------
// Artwork path
// ---------------------------------------------------------------------------

function artworkSvg({ title, section, kicker, caption }) {
  const palette = PALETTES[section] || PALETTES.default;
  const dark = isDarkPalette(section);
  const ink = dark ? BRAND.white : BRAND.ink;
  const sub = dark ? 'rgba(255,255,255,0.78)' : BRAND.muted;
  const seed = hashSlug(title, section.length);

  const parts = [];
  parts.push(`<defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="${palette.from}"/>
      <stop offset="100%" stop-color="${palette.to}"/>
    </linearGradient>
    <linearGradient id="badge" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="${palette.accent}"/>
      <stop offset="100%" stop-color="${palette.deep}"/>
    </linearGradient>
  </defs>`);
  parts.push(`<rect width="${WIDTH}" height="${HEIGHT}" fill="url(#bg)"/>`);

  // Motif: a big translucent ring plus a solid disc, placed by the slug hash so
  // every post gets a different composition without any stored state.
  const ringX = 780 + (seed % 220);
  const ringY = 110 + ((seed >> 5) % 180);
  const ringR = 190 + ((seed >> 9) % 90);
  const discX = 690 + ((seed >> 3) % 320);
  const discY = 300 + ((seed >> 7) % 240);
  const discR = 60 + ((seed >> 11) % 70);
  const arcX = 60 + ((seed >> 4) % 200);
  const arcY = 420 + ((seed >> 6) % 180);

  parts.push(`<circle cx="${ringX}" cy="${ringY}" r="${ringR}" fill="none" stroke="${palette.accent}" stroke-opacity="0.28" stroke-width="26"/>`);
  parts.push(`<circle cx="${discX}" cy="${discY}" r="${discR}" fill="${palette.accent}" fill-opacity="0.16"/>`);
  parts.push(`<circle cx="${discX}" cy="${discY}" r="${discR * 0.45}" fill="url(#badge)" fill-opacity="0.9"/>`);
  parts.push(`<path d="M ${arcX} ${arcY} a 96 96 0 0 1 192 0" fill="none" stroke="${palette.deep}" stroke-opacity="0.35" stroke-width="18" stroke-linecap="round"/>`);

  // Title block. Sized down until it fits three lines inside the text column.
  const maxTextWidth = WIDTH - MARGIN * 2 - 34;
  let size = 66;
  let lines = wrapLines(title, size, 700, maxTextWidth, 3);
  while (size > 40 && lines.length >= 3) {
    size -= 4;
    lines = wrapLines(title, size, 700, maxTextWidth, 3);
  }
  const lineHeight = Math.round(size * 1.16);
  const titleHeight = lines.length * lineHeight;

  const kickerSize = 19;
  const captionSize = 18;
  const gap = 16;
  const blockHeight = kickerSize + gap + titleHeight + gap + captionSize;
  const bottom = HEIGHT - MARGIN - 24;
  const top = Math.max(MARGIN + 20, bottom - blockHeight);

  const barX = MARGIN;
  const textX = MARGIN + 30;
  let cursor = top;

  parts.push(`<rect x="${barX}" y="${top + 2}" width="9" height="${blockHeight - captionSize - gap - 4}" fill="url(#badge)" rx="4"/>`);
  parts.push(`<text x="${textX}" y="${cursor + kickerSize - 5}" font-family="${SANS}" font-size="${kickerSize}" font-weight="700" letter-spacing="2.4" fill="${palette.accent}">${escapeXml(kicker.toUpperCase())}</text>`);
  cursor += kickerSize + gap;

  for (const line of lines) {
    parts.push(`<text x="${textX}" y="${cursor + size * 0.8}" font-family="${SERIF}" font-size="${size}" font-weight="700" fill="${ink}">${escapeXml(line)}</text>`);
    cursor += lineHeight;
  }

  cursor += gap;
  parts.push(`<text x="${textX}" y="${cursor + captionSize - 6}" font-family="${SANS}" font-size="${captionSize}" font-weight="400" fill="${sub}">${escapeXml(caption)}</text>`);

  // Caption slot rule: a thin brand line under the byline.
  parts.push(`<rect x="${textX}" y="${bottom + 8}" width="72" height="4" fill="url(#badge)" rx="2"/>`);

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">${parts.join('')}</svg>`;
}

// The in-article figure. Same palette language as the cover but a wider 3:2
// canvas and a quieter motif, so the two never read as duplicates.
function bodyArtworkSvg({ title, section }) {
  const palette = PALETTES[section] || PALETTES.default;
  const dark = isDarkPalette(section);
  const ink = dark ? BRAND.white : BRAND.ink;
  const sub = dark ? 'rgba(255,255,255,0.72)' : BRAND.muted;
  const seed = hashSlug(title, section.length + 11);

  const parts = [];
  parts.push(`<defs>
    <linearGradient id="bbg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="${dark ? palette.to : palette.from}"/>
      <stop offset="100%" stop-color="${dark ? palette.deep : palette.tint}"/>
    </linearGradient>
    <linearGradient id="bbadge" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="${palette.accent}"/>
      <stop offset="100%" stop-color="${palette.deep}"/>
    </linearGradient>
  </defs>`);
  parts.push(`<rect width="${BODY_WIDTH}" height="${BODY_HEIGHT}" fill="url(#bbg)"/>`);

  const cx = 900 + (seed % 200);
  const cy = 240 + ((seed >> 4) % 220);
  const r = 150 + ((seed >> 7) % 110);
  const dotX = 180 + ((seed >> 3) % 160);
  const dotY = 520 + ((seed >> 6) % 140);
  parts.push(`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${palette.accent}" stroke-opacity="0.3" stroke-width="22"/>`);
  parts.push(`<circle cx="${cx - r * 0.55}" cy="${cy + r * 0.6}" r="${r * 0.34}" fill="${palette.accent}" fill-opacity="0.14"/>`);
  parts.push(`<circle cx="${dotX}" cy="${dotY}" r="16" fill="url(#bbadge)" fill-opacity="0.85"/>`);
  parts.push(`<path d="M 90 640 a 120 120 0 0 1 240 0" fill="none" stroke="${palette.deep}" stroke-opacity="0.28" stroke-width="16" stroke-linecap="round"/>`);

  // Small brand block, bottom-left, so the figure carries the site identity.
  parts.push(`<text x="72" y="700" font-family="${SANS}" font-size="20" font-weight="700" letter-spacing="3" fill="${palette.accent}">COUPLE IN BOND</text>`);
  parts.push(`<text x="72" y="730" font-family="${SANS}" font-size="17" font-weight="400" fill="${sub}">${escapeXml(section)}</text>`);
  parts.push(`<text x="72" y="60" font-family="${SANS}" font-size="15" font-weight="400" fill="${sub}">${escapeXml(title)}</text>`);

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${BODY_WIDTH}" height="${BODY_HEIGHT}" viewBox="0 0 ${BODY_WIDTH} ${BODY_HEIGHT}">${parts.join('')}</svg>`;
}

// ---------------------------------------------------------------------------
// Photo path
// ---------------------------------------------------------------------------

function scrimSvg() {
  const stops = [];
  for (let i = 0; i <= 10; i += 1) {
    const at = i / 10;
    const opacity = at < 0.4 ? 0 : Math.round(((at - 0.4) / 0.6) * 205) / 255;
    stops.push(`<stop offset="${(at * 100).toFixed(0)}%" stop-color="#14091a" stop-opacity="${opacity.toFixed(3)}"/>`);
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">
  <defs>
    <linearGradient id="scrim" x1="0" y1="0" x2="0" y2="1">${stops.join('')}</linearGradient>
    <linearGradient id="scrimLeft" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#14091a" stop-opacity="0.5"/>
      <stop offset="48%" stop-color="#14091a" stop-opacity="0"/>
    </linearGradient>
  </defs>
  <rect width="${WIDTH}" height="${HEIGHT}" fill="url(#scrim)"/>
  <rect width="${WIDTH}" height="${HEIGHT}" fill="url(#scrimLeft)"/>
</svg>`;
}

// In-article photo treatment: a 3:2 crop with a soft bottom-up scrim and a
// small brand lockup, so it is clearly not the same crop as the cover.
function bodyPhotoSvg({ section }) {
  const palette = PALETTES[section] || PALETTES.default;
  const dark = isDarkPalette(section);
  const label = dark ? BRAND.white : BRAND.ink;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${BODY_WIDTH}" height="${BODY_HEIGHT}" viewBox="0 0 ${BODY_WIDTH} ${BODY_HEIGHT}">
  <defs>
    <linearGradient id="bscrim" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#14091a" stop-opacity="0"/>
      <stop offset="70%" stop-color="#14091a" stop-opacity="0.45"/>
      <stop offset="100%" stop-color="#14091a" stop-opacity="0.72"/>
    </linearGradient>
  </defs>
  <rect width="${BODY_WIDTH}" height="${BODY_HEIGHT}" fill="url(#bscrim)"/>
  <rect x="72" y="700" width="6" height="52" fill="${palette.accent}" rx="3"/>
  <text x="96" y="724" font-family="${SANS}" font-size="19" font-weight="700" letter-spacing="2.6" fill="${label}">COUPLE IN BOND</text>
  <text x="96" y="748" font-family="${SANS}" font-size="16" font-weight="400" fill="${label}" fill-opacity="0.72">${escapeXml(section)}</text>
</svg>`;
}

function photoOverlaySvg({ title, kicker, caption }) {
  const maxTextWidth = WIDTH - MARGIN * 2 - 34;
  let size = 62;
  let lines = wrapLines(title, size, 700, maxTextWidth, 3);
  while (size > 38 && lines.length >= 3) {
    size -= 4;
    lines = wrapLines(title, size, 700, maxTextWidth, 3);
  }
  const lineHeight = Math.round(size * 1.14);
  const titleHeight = lines.length * lineHeight;
  const kickerSize = 19;
  const captionSize = 17;
  const gap = 15;
  const blockHeight = kickerSize + gap + titleHeight + gap + captionSize;
  const bottom = HEIGHT - MARGIN;
  const top = bottom - blockHeight;
  const barX = MARGIN;
  const textX = MARGIN + 26;
  const shadow = 'paint-order="stroke" stroke="#14091a" stroke-width="3" stroke-linejoin="round"';

  const parts = [];
  parts.push(`<rect x="${barX}" y="${top + 4}" width="8" height="${blockHeight - captionSize - gap - 8}" fill="${BRAND.primary}" rx="3"/>`);
  parts.push(`<text x="${textX}" y="${top + kickerSize - 5}" font-family="${SANS}" font-size="${kickerSize}" font-weight="700" letter-spacing="2.2" fill="${BRAND.primary}" ${shadow}>${escapeXml(kicker.toUpperCase())}</text>`);
  let cursor = top + kickerSize + gap;
  for (const line of lines) {
    parts.push(`<text x="${textX}" y="${cursor + size * 0.82}" font-family="${SERIF}" font-size="${size}" font-weight="700" fill="${BRAND.white}" ${shadow}>${escapeXml(line)}</text>`);
    cursor += lineHeight;
  }
  cursor += gap;
  parts.push(`<text x="${textX}" y="${cursor + captionSize - 6}" font-family="${SANS}" font-size="${captionSize}" font-weight="400" fill="rgba(255,255,255,0.8)" ${shadow}>${escapeXml(caption)}</text>`);
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">${parts.join('')}</svg>`;
}

// ---------------------------------------------------------------------------
// Frontmatter
// ---------------------------------------------------------------------------

function patchFrontmatter(post, { coverImage, alt, body }) {
  const block = [
    `coverImage: "${coverImage}"`,
    `coverImageAlt: "${alt.replace(/"/g, "'")}"`,
  ].join('\n');
  const existing = post.frontmatterText.replace(/^coverImage(Alt|Credit|CreditUrl)?:.*\r?\n/gm, '');
  return `---\n${existing}\n${block}\n---\n${body ?? post.body}`;
}

function bodyFigure({ key, alt, caption }) {
  return [
    BODY_START,
    `<figure class="article-figure"><img src="/assets/blog/${key}-body.jpg" alt="${escapeHtml(alt)}" width="${BODY_WIDTH}" height="${BODY_HEIGHT}" loading="lazy" decoding="async"><figcaption>${escapeHtml(caption)}</figcaption></figure>`,
    BODY_END,
  ].join('\n');
}

// Replace an existing figure, or insert one after the first paragraph -- the
// same anchor the repo's blog-images.mjs uses, so the two never disagree.
function insertBodyFigure(body, figure) {
  const existing = body.match(new RegExp(`${escapeRegExp(BODY_START)}[\\s\\S]*?${escapeRegExp(BODY_END)}\\r?\\n?`));
  if (existing) return body.replace(existing[0], figure);
  const anchor = body.indexOf('</p>');
  if (anchor === -1) throw new Error('body has no paragraph to anchor the figure to');
  const at = anchor + '</p>'.length;
  return `${body.slice(0, at)}\n\n${figure}\n\n${body.slice(at)}`;
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function render({ post, sample, mode, outDir }) {
  const title = post.frontmatter.title || post.frontmatter.pageTitle || post.slug;
  const section = post.frontmatter.section || 'Relationships';
  const kicker = [
    section,
    (post.frontmatter.kicker || '').split('·')[1]?.trim() || '',
  ].filter(Boolean).join('  ·  ');
  const caption = [
    post.frontmatter.author || 'Couple in Bond Editorial',
    post.frontmatter.publishedLabel || post.frontmatter.datePublished || '',
  ].filter(Boolean).join('  ·  ');

  const key = sample ? `${post.slug}-${sample.key}` : `${post.slug}-cover`;
  const outPath = path.join(outDir, `${key}.jpg`);
  const bodyPath = path.join(outDir, `${key}-body.jpg`);
  const coverImage = `/assets/blog/${key}.jpg`;
  // bodyFigure() appends "-body.jpg", so this stays the bare cover key.
  const bodyKey = key;

  if (sample) {
    const base = await sharp(sample.file)
      .resize(WIDTH, HEIGHT, { fit: 'cover', position: sharp.strategy.attention })
      .jpeg({ quality: 82, mozjpeg: true })
      .toBuffer();
    await sharp(base)
      .composite([
        { input: Buffer.from(scrimSvg()) },
        { input: Buffer.from(photoOverlaySvg({ title, kicker, caption })) },
      ])
      .jpeg({ quality: 86, mozjpeg: true })
      .toFile(outPath);

    const bodyBase = await sharp(sample.file)
      .resize(BODY_WIDTH, BODY_HEIGHT, { fit: 'cover', position: 'centre' })
      .jpeg({ quality: 80, mozjpeg: true })
      .toBuffer();
    await sharp(bodyBase)
      .composite([{ input: Buffer.from(bodyPhotoSvg({ section })) }])
      .jpeg({ quality: 84, mozjpeg: true })
      .toFile(bodyPath);

    return {
      outPath,
      bodyPath,
      coverImage,
      bodyKey,
      alt: altForPhoto(title, section),
      bodyAlt: bodyAltForPhoto(section),
      bodyCaption: `Illustration from the ${section} series`,
      sampleKey: sample.key,
    };
  }

  await sharp(Buffer.from(artworkSvg({ title, section, kicker, caption })))
    .jpeg({ quality: 88, mozjpeg: true })
    .toFile(outPath);
  await sharp(Buffer.from(bodyArtworkSvg({ title, section })))
    .jpeg({ quality: 86, mozjpeg: true })
    .toFile(bodyPath);

  return {
    outPath,
    bodyPath,
    coverImage,
    bodyKey,
    alt: `Cover artwork for ${title}`,
    bodyAlt: `In-article artwork for the ${section} series`,
    bodyCaption: `${section} · Couple in Bond`,
    sampleKey: null,
  };
}

function altForPhoto(title, section) {
  return `Cover photograph for the ${section} article ${title}`;
}

function bodyAltForPhoto(section) {
  return `In-article photograph from the ${section} series`;
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help) {
    console.log('node scripts/cover-generator.mjs [--slug <slug>] [--all] [--force] [--check] [--mode auto|artwork|photo] [--out <dir>]');
    return;
  }

  const posts = listPosts();
  if (!posts.length) throw new Error(`no posts found in ${blogDir}`);

  const samples = options.mode === 'photo'
    ? listSampleCovers()
    : (options.mode === 'artwork' ? [] : listSampleCovers());
  if (options.mode === 'photo' && !samples.length) {
    throw new Error(`--mode photo needs *-cover.jpg files in ${sampleDir}`);
  }

  const targets = options.all
    ? posts
    : options.slug
      ? [posts.find((post) => post.slug === options.slug) || (() => { throw new Error(`no post with slug "${options.slug}"`); })()]
      : posts.filter((post) => options.force || !post.frontmatter.coverImage);

  if (options.check) {
    const missing = posts.filter((post) => !post.frontmatter.coverImage || !post.body.includes(BODY_START));
    if (missing.length) {
      console.error(`${missing.length} post(s) missing a cover or in-article figure:`);
      for (const post of missing) {
        const gaps = [];
        if (!post.frontmatter.coverImage) gaps.push('cover');
        if (!post.body.includes(BODY_START)) gaps.push('figure');
        console.error(`  ${post.slug} (${gaps.join(' + ')})`);
      }
      process.exit(1);
    }
    console.log(`OK: all ${posts.length} posts have a cover and in-article figure.`);
    return;
  }

  fs.mkdirSync(options.out, { recursive: true });
  for (const post of targets) {
    const sample = samples.length
      ? samples[hashSlug(post.slug, targets.length) % samples.length]
      : null;
    const result = await render({ post, sample, mode: options.mode, outDir: options.out });
    post.frontmatter.coverImage = result.coverImage;
    post.frontmatter.coverImageAlt = result.alt;
    const figure = bodyFigure({ key: result.bodyKey, alt: result.bodyAlt, caption: result.bodyCaption });
    fs.writeFileSync(post.file, patchFrontmatter(post, { ...result, body: insertBodyFigure(post.body, figure) }));
    console.log(`  ${post.slug} -> ${path.relative(rootDir, result.outPath)} + ${path.relative(rootDir, result.bodyPath)}${result.sampleKey ? ` (${result.sampleKey})` : ' (artwork)'}`);
  }
  console.log(`Covers ready: ${targets.length} post(s), ${samples.length ? 'photo' : 'artwork'} mode.`);
}

if (process.argv[1] === __filename) {
  main().catch((error) => {
    console.error(error.message || error);
    process.exit(1);
  });
}

export { render as generateCover, listPosts, listSampleCovers };
